SELECT COUNT(*) FROM postHistory as ph, comments as c, posts as p, users as u WHERE p.OwnerUserId = u.Id AND c.UserId = u.Id AND ph.UserId = u.Id AND ph.CreationDate<=CAST('2014-09-02 07:58:47' AS TIMESTAMP) AND c.Score=2 AND p.AnswerCount>=0 AND p.AnswerCount<=9 AND p.CreationDate>=CAST('2010-07-20 18:17:25' AS TIMESTAMP) AND p.CreationDate<=CAST('2014-08-26 12:57:22' AS TIMESTAMP)
